<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><title>{{ $receivingRecord->receiving_number ?? 'Receiving Draft' }}</title><style>body{font-family:Arial,sans-serif;color:#0f172a;margin:32px}table{width:100%;border-collapse:collapse;margin-top:24px}th,td{border:1px solid #cbd5e1;padding:8px}.num{text-align:right}</style></head><body><h1>RECEIVING RECORD</h1><p><strong>Number:</strong> {{ $receivingRecord->receiving_number ?? 'DRAFT' }}</p><p><strong>Purchase order:</strong> {{ $receivingRecord->purchaseOrder->purchase_order_number }}</p><p><strong>Supplier:</strong> {{ $receivingRecord->supplier_name }}</p><p><strong>Date:</strong> {{ $receivingRecord->receiving_date->format('M d, Y') }}</p><table><thead><tr><th>Item</th><th class="num">Received</th><th class="num">Accepted</th><th class="num">Rejected</th><th>Reason</th></tr></thead><tbody>@foreach($receivingRecord->lines as $line)<tr><td>{{ $line->description }}</td><td class="num">{{ $line->received_quantity }}</td><td class="num">{{ $line->accepted_quantity }}</td><td class="num">{{ $line->rejected_quantity }}</td><td>{{ $line->rejection_reason }}</td></tr>@endforeach</tbody></table></body></html>
